using System;using System.Diagnostics;using System.IO;using System.Windows.Forms;
class PairLauncher{[STAThread]static void Main(){try{string root=AppDomain.CurrentDomain.BaseDirectory,script=Path.Combine(root,"Vincular-TRIGGERcmd.ps1");var start=new ProcessStartInfo("powershell.exe","-NoProfile -NonInteractive -ExecutionPolicy Bypass -File \""+script+"\""){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden,RedirectStandardOutput=true,RedirectStandardError=true};using(var process=Process.Start(start)){string output=process.StandardOutput.ReadToEnd(),error=process.StandardError.ReadToEnd();process.WaitForExit();if(process.ExitCode!=0)throw new Exception(String.IsNullOrWhiteSpace(error)?"Confira o celular e prepare o vínculo no aplicativo.":error);MessageBox.Show(output,"Vincular TRIGGERcmd",MessageBoxButtons.OK,MessageBoxIcon.Information);}}catch(Exception e){MessageBox.Show(e.Message,"Vincular TRIGGERcmd",MessageBoxButtons.OK,MessageBoxIcon.Error);}}}
